import{_ as t,H as r,f as n,b as p,j as a,i}from"./chunks/framework.BH2BK_3i.js";const m=JSON.parse('{"title":"01 数学基础 | 九层之台，起于累土：线性代数","description":"","frontmatter":{},"headers":[],"relativePath":"人工智能基础课/01数学基础-九层之台，起于累土：线性代数.md","filePath":"人工智能基础课/01数学基础-九层之台，起于累土：线性代数.md","lastUpdated":1779818127000}'),l={name:"人工智能基础课/01数学基础-九层之台，起于累土：线性代数.md"};function s(_,e,o,c,g,$){return r(),n("div",null,[...e[0]||(e[0]=[p("h1",{id:"_01-数学基础-九层之台-起于累土-线性代数",tabindex:"-1"},[a("01 数学基础 | 九层之台，起于累土：线性代数 "),p("a",{class:"header-anchor",href:"#_01-数学基础-九层之台-起于累土-线性代数","aria-label":'Permalink to "01 数学基础 | 九层之台，起于累土：线性代数"'},"​")],-1),p("p",null,"“人工智能基础课”将从数学基础开始。必备的数学知识是理解人工智能不可或缺的要素，今天的种种人工智能技术归根到底都建立在数学模型之上，而这些数学模型又都离不开线性代数（linear algebra）的理论框架。",-1),p("p",null,[a("事实上，线性代数不仅仅是人工智能的基础，更是现代数学和以现代数学作为主要分析方法的众多学科的基础。从量子力学到图像处理都离不开向量和矩阵的使用。而在向量和矩阵背后，线性代数的核心意义在于提供了⼀种看待世界的抽象视角： "),p("strong",null,"万事万物都可以被抽象成某些特征的组合，并在由预置规则定义的框架之下以静态和动态的方式加以观察"),a("。")],-1),p("p",null,"线性代数中最基本的概念是集合（set）。在数学上，集合的定义是由某些特定对象汇总而成的集体。集合中的元素通常会具有某些共性，因而可以用这些共性来表示。对于集合 { 苹果，橘子，梨 } 来说， 所有元素的共性是它们都是水果；对于集合 {牛，马，羊} 来说，所有元素的共性是它们都是动物。当然 { 苹果，牛 } 也可以构成一个集合，但这两个元素并没有明显的共性，这样的集合在解决实际问题中的作用也就相当有限。",-1),p("p",null,"“苹果”或是“牛”这样的具体概念显然超出了数学的处理范围，因而集合的元素需要进行进一步的抽象——用数字或符号来表示。如此一来，集合的元素既可以是单个的数字或符号，也可以是多个数字或符号以某种方式排列形成的组合。",-1),p("p",null,"在线性代数中，由单独的数a构成的元素被称为标量（scalar）：一个标量a可以是整数、实数或复数。如果多个标量${ a_1, a_2, \\cdots, a_n}$ 按一定顺序组成一个序列，这样的元素就被称为向量（vector）。显然，向量可以看作标量的扩展。原始的一个数被替代为一组数，从而带来了维度的增加，给定表示索引的下标才能唯一地确定向量中的元素。",-1),p("p",null,"每个向量都由若干标量构成，如果将向量的所有标量都替换成相同规格的向量，得到的就是如下的矩阵（matrix）:",-1),p("p",{cc:""},"$$\\left( {\\begin{array}",-1),i("",36)])])}const d=t(l,[["render",s]]);export{m as __pageData,d as default};
